export function fixture(name) {
 let positions,normals,colors;
 if(name.startsWith('plane')) {
  const side=350;positions=new Float32Array(side*side*18);normals=new Float32Array(positions.length);
  for(let y=0,at=0;y<side;y++)for(let x=0;x<side;x++,at+=18)positions.set([x,y,0,x+1,y,0,x,y+1,0,x+1,y,0,x+1,y+1,0,x,y+1,0],at);
  for(let at=2;at<normals.length;at+=3)normals[at]=1;
  if(name==='plane-color'){colors=new Float32Array(positions.length);for(let at=0;at<colors.length;at++)colors[at]=(at%3===0?1:0);}
  if(name==='plane-seam'){colors=new Float32Array(positions.length);for(let at=0;at<colors.length;at++)colors[at]=(at%3===0?(positions[at]<175?1:0):0);}
 } else {
  const geometry=name==='closedBox'?new BoxGeometry(1,1,1,166,166,166):new SphereGeometry(1,160,100);
  const triangles=geometry.toNonIndexed();geometry.dispose();positions=triangles.getAttribute('position').array;normals=triangles.getAttribute('normal').array;
  if(name==='curved-color')colors=Float32Array.from(positions,(_v,i)=>(i%13)/12);triangles.dispose();
 }
 return {meshes:[{name,positions,normals,colors,groups:[]}],root:{name:'',meshes:[0],children:[]}};
}
export const names=['plane','plane-color','closedBox','curved-color','plane-seam'];
export function signature(model) {
 const hash=crypto.createHash('sha256');
 hash.update(JSON.stringify({root:model.root,meshes:model.meshes.map(({name,groups})=>({name,groups}))}));
 for(const mesh of model.meshes)for(const key of ['positions','normals','colors','indices']){
  hash.update(key);if(mesh[key])hash.update(Buffer.from(mesh[key].buffer,mesh[key].byteOffset,mesh[key].byteLength));else hash.update('undefined');
 }
 return hash.digest('hex');
}
export function equal(a,b) {
 assert.deepEqual(a.root,b.root);
 for(let m=0;m<a.meshes.length;m++)for(const key of ['positions','normals','colors','indices']){
  const before=a.meshes[m][key],after=b.meshes[m][key];
  assert.equal(Boolean(before),Boolean(after));if(before)assert.ok(Buffer.from(before.buffer,before.byteOffset,before.byteLength).equals(Buffer.from(after.buffer,after.byteOffset,after.byteLength)),`Different full ${key} output`);
 }
