import fs from 'node:fs';
import {fixture,names,signature,equal} from './fixtures.mjs';
import * as baseline from './baseline.mjs';
const variants=process.argv.slice(2).length?process.argv.slice(2):['attributes','indices','combined'];
const results=[];
for(const variant of variants){
 const candidate=await import(`./${variant}.mjs`);
 const [basePlanar,candidatePlanar]=await Promise.all([import('./baseline-planar.mjs'),import(`./${variant}-planar.mjs`)]);
 for(const name of names){
  const model=fixture(name), indexed={...model,meshes:model.meshes.map(mesh=>baseline.indexMesh(mesh,Infinity))};
  for(const phase of ['full','planar']){
   const input=phase==='full'?model:indexed;
   const run=phase==='full'?{baseline:baseline.optimizeModel,candidate:candidate.optimizeModel}:{baseline:(m,d)=>({...m,meshes:m.meshes.map(mesh=>basePlanar.planarMesh(mesh,d))}),candidate:(m,d)=>({...m,meshes:m.meshes.map(mesh=>candidatePlanar.planarMesh(mesh,d))})};
   for(let i=0;i<4;i++){run.baseline(input,Infinity);run.candidate(input,Infinity);}
   const rows=[];
   for(let pair=0;pair<12;pair++){
    const row={pair},outputs={};
    for(const label of pair%2?['candidate','baseline']:['baseline','candidate']){
     const start=performance.now();outputs[label]=run[label](input,Infinity);row[label]=performance.now()-start;
    }
    equal(outputs.baseline,outputs.candidate);row.signature=signature(outputs.baseline);rows.push(row);
   }
   const median=key=>{const times=rows.map(row=>row[key]).sort((a,b)=>a-b);return(times[5]+times[6])/2;};
   const baselineMedianMs=median('baseline'),candidateMedianMs=median('candidate');
   const result={variant,name,phase,vertices:model.meshes[0].positions.length/3,indexedVertices:indexed.meshes[0].positions.length/3,warmupPairs:4,pairs:12,baselineMedianMs,candidateMedianMs,reductionPercent:100*(baselineMedianMs-candidateMedianMs)/baselineMedianMs,rows};results.push(result);
   console.log(JSON.stringify({...result,rows:undefined}));
   fs.writeFileSync('/tmp/pr517-planar-experiment/results.json',JSON.stringify(results,null,2));
  }
 }
}

