import fs from 'node:fs';
import {spawnSync} from 'node:child_process';
import {fixture,signature} from './fixtures.mjs';
if(process.argv[2]==='child'){
 const [variant,name]=process.argv.slice(3),{indexMesh}=await import(`./${variant}.mjs`),{planarMesh}=await import(`./${variant}-planar.mjs`);
 const model=fixture(name),mesh=model.meshes[0];
 let start=performance.now();const indexed=indexMesh(mesh,Infinity),indexMs=performance.now()-start;
 start=performance.now();const output=planarMesh(indexed,Infinity),planarMs=performance.now()-start;
 console.log(JSON.stringify({variant,name,indexMs,planarMs,preparationMs:indexMs+planarMs,signature:signature({...model,meshes:[output]})}));
}else{
 const variant=process.argv[2]||'combined',rows=[];
 for(const name of ['plane','closedBox','curved-color'])for(let pair=0;pair<4;pair++){
  const result={name,pair};
  for(const label of pair%2?[variant,'baseline']:['baseline',variant]){
   const child=spawnSync(process.execPath,[import.meta.filename,'child',label,name],{encoding:'utf8'});if(child.status!==0)throw Error(child.stderr);result[label]=JSON.parse(child.stdout);
  }
  if(result.baseline.signature!==result[variant].signature)throw Error('Cold output mismatch');rows.push(result);console.log(JSON.stringify(result));
 }
 fs.writeFileSync('/tmp/pr517-planar-experiment/cold-results.json',JSON.stringify(rows,null,2));
}

